    expect(applyPatch({ text: row.base }, forward, true, false).newDocument.text).toBe(row.expected.state);
    const inverse: Operation[] = row.inverseRefused || row.applyRefused ? [] : [{ op: "replace", path: "/text", value: row.base }];
